_CORE_SRC = '# Diagnosis:\n# The report contains no losses or draws for the champion, in either seat.\n# Its smallest advantage is against marginal greedy play, however, so there is\n# no evidence that its opponent model is adequate against stronger opponents.\n# In particular, it predicts against stationary friendly capacity, even while\n# planning moving friendly couriers. Its prediction therefore misses both the\n# opponent\'s response to our destinations and the resulting stock depletion.\n# Its narrow, unconstrained beam can also discard every route through a poor\n# intermediate node before reaching a replenished destination.\n#\n# Changes:\n# 1. Predict legal opponent trajectories against our actual reserved paths, then\n#    refresh that best response after our first planning pass. Blend predictions\n#    with observed persistence rather than treating all opponents as mobile.\n# 2. Use a longer, spatially diverse trajectory beam, with exact stock dynamics,\n#    margin/denial scoring, return liabilities, and incumbent-plan protection.\n# Action construction and start-of-turn legality checks remain deliberately simple.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nCAP = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_key = None\n        self.dist = []\n        self.reach = {}\n        self.plan = {}\n        self.last_turn = None\n        self.previous_opponent = {}\n        self.mobility = None\n        self.bad_reports = 0\n        self.conservative = False\n\n    def _prepare(self, obs):\n        n = int(obs["n_nodes"])\n        key = (n, tuple(tuple(e) for e in obs["edges"]))\n        if key != self.map_key:\n            adj = [[] for _ in range(n)]\n            for a, b in obs["edges"]:\n                adj[a].append(b)\n                adj[b].append(a)\n            for row in adj:\n                row.sort()\n            distances = []\n            for source in range(n):\n                d = [-1] * n\n                d[source] = 0\n                q = deque([source])\n                while q:\n                    u = q.popleft()\n                    for v in adj[u]:\n                        if d[v] < 0:\n                            d[v] = d[u] + 1\n                            q.append(v)\n                distances.append(d)\n            self.dist = distances\n            self.reach = {\n                speed: [\n                    [v for v in range(n) if 0 <= distances[u][v] <= speed]\n                    for u in range(n)\n                ]\n                for speed in (1, 2)\n            }\n            self.map_key = key\n            self.plan = {}\n        if (obs.get("n_invalid_actions_last_turn", 0) > 0\n                or not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n\n    @staticmethod\n    def _capacities(units, plan, horizon, n):\n        result = [[0.0] * n for _ in range(horizon)]\n        for uid in sorted(units):\n            capacity = CAP[units[uid][0]]\n            path = plan[uid]\n            for t in range(horizon):\n                result[t][path[t]] += capacity\n        return result\n\n    def _warm(self, units, turn, horizon):\n        consecutive = self.last_turn is not None and turn == self.last_turn + 1\n        result = {}\n        for uid in sorted(units):\n            kind, source = units[uid]\n            old = self.plan.get(uid, [])\n            old = old[1:] if consecutive else []\n            path = []\n            position = source\n            for t in range(horizon):\n                v = old[t] if t < len(old) else position\n                if not (0 <= v < len(self.dist)\n                        and 0 <= self.dist[position][v] <= SPEED[kind]):\n                    v = position\n                path.append(v)\n                position = v\n            result[uid] = path\n        return result\n\n    def _activity(self, obs):\n        opponents = obs["opponent_units"]\n        base = obs["opponent_base"]\n        if self.last_turn is not None and obs["turn"] == self.last_turn + 1:\n            active = 0\n            moved = 0\n            for uid in sorted(opponents):\n                if uid not in self.previous_opponent:\n                    continue\n                now = opponents[uid][1]\n                old = self.previous_opponent[uid]\n                if now != base or old != base:\n                    active += 1\n                    moved += int(now != old)\n            rate = moved / max(1, active)\n            self.mobility = (rate if self.mobility is None\n                             else 0.65 * self.mobility + 0.35 * rate)\n        if self.mobility is None:\n            return 0.86\n        all_home = all(node == base for _, node in opponents.values())\n        if all_home and int(obs["turn"]) >= 2 and self.mobility < 0.08:\n            return 0.04\n        return min(0.95, 0.22 + 0.95 * self.mobility)\n\n    def _greedy(self, units, base, opponent, obs, horizon):\n        """Cheap legal rollout; also supplies an immediately usable fallback."""\n        n = obs["n_nodes"]\n        stocks = list(obs["stock"])\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        positions = {uid: data[1] for uid, data in units.items()}\n        plan = {uid: [] for uid in units}\n        preferred = "truck" if obs["turn"] < 4 else "scooter"\n        ids = sorted(units, key=lambda u: (units[u][0] != preferred, u))\n        for t in range(horizon):\n            allocated = [0.0] * n\n            for uid in ids:\n                kind = units[uid][0]\n                capacity, cost, speed = CAP[kind], COST[kind], SPEED[kind]\n                source = positions[uid]\n                best = source\n                best_value = -1e100\n                for v in self.reach[speed][source]:\n                    a, b, s = allocated[v], opponent[t][v], stocks[v]\n                    denominator = max(a + b, s)\n                    before = (a - b) * s / denominator if denominator > 0 else 0.0\n                    denominator = max(a + capacity + b, s)\n                    after = ((a + capacity - b) * s / denominator\n                             if denominator > 0 else 0.0)\n                    value = after - before\n                    if v != base:\n                        value -= cost\n                        home_steps = (self.dist[v][base] + speed - 1) // speed\n                        if obs["turn"] + t < 58:\n                            value -= 0.32 * cost * max(0, home_steps - 1)\n                    if v != source:\n                        value -= 0.012\n                    if value > best_value + 1e-10:\n                        best_value, best = value, v\n                positions[uid] = best\n                plan[uid].append(best)\n                allocated[best] += capacity\n            for v in range(n):\n                stocks[v] = round(min(\n                    maximum[v],\n                    max(0.0, stocks[v] - allocated[v] - opponent[t][v]) + regen[v]\n                ), 2)\n        return plan\n\n    def _forecast(self, units, plan, activity, horizon, n):\n        predicted = self._capacities(units, plan, horizon, n)\n        frozen = [0.0] * n\n        for kind, v in units.values():\n            frozen[v] += CAP[kind]\n        for t in range(horizon):\n            weight = min(0.98, activity + 0.025 * t)\n            predicted[t] = [\n                weight * predicted[t][v] + (1.0 - weight) * frozen[v]\n                for v in range(n)\n            ]\n        return predicted\n\n    def _optimize(self, uid, units, base, plan, opponent, obs,\n                  horizon, width, deadline):\n        n = obs["n_nodes"]\n        kind, source = units[uid]\n        capacity, cost, speed = CAP[kind], COST[kind], SPEED[kind]\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        fixed = [[0.0] * n for _ in range(horizon)]\n        for other in sorted(units):\n            if other != uid:\n                c = CAP[units[other][0]]\n                for t, v in enumerate(plan[other]):\n                    fixed[t][v] += c\n\n        discounts = [0.97 ** t for t in range(horizon)]\n        terminal_weight = min(1.0, max(0, 60 - obs["turn"] - horizon) / 3.0)\n        liabilities = [\n            terminal_weight * 0.75 * cost\n            * max(0, (self.dist[v][base] + speed - 1) // speed - 1)\n            for v in range(n)\n        ]\n\n        # Protect the incumbent: approximate beam pruning must never turn a\n        # completed coordinate update into a reduction of the same objective.\n        old_path = plan[uid]\n        stocks = list(obs["stock"])\n        old_score = 0.0\n        position = source\n        for t in range(horizon):\n            v = old_path[t]\n            reward = 0.0\n            for node in range(n):\n                a = fixed[t][node] + (capacity if node == v else 0)\n                b = opponent[t][node]\n                s = stocks[node]\n                denominator = max(a + b, s)\n                if denominator > 0:\n                    reward += (a - b) * s / denominator\n                stocks[node] = round(min(\n                    maximum[node], max(0.0, s - a - b) + regen[node]\n                ), 2)\n            if v != base:\n                reward -= cost\n            if v != position:\n                reward -= 0.012\n            old_score += discounts[t] * reward\n            position = v\n        old_rank = old_score - discounts[-1] * liabilities[position]\n\n        # score, current node, exact stock vector, path\n        beam = [(0.0, source, list(obs["stock"]), [])]\n        final_rank = -1e100\n        for t in range(horizon):\n            if time.perf_counter() >= deadline:\n                return None\n            children = []\n            fixed_cap = fixed[t]\n            opp_cap = opponent[t]\n            discount = discounts[t]\n            for score, position, stocks, path in beam:\n                if time.perf_counter() >= deadline:\n                    return None\n                baseline = 0.0\n                revenue = [0.0] * n\n                next_stock = [0.0] * n\n                for v in range(n):\n                    a, b, s = fixed_cap[v], opp_cap[v], stocks[v]\n                    denominator = max(a + b, s)\n                    value = ((a - b) * s / denominator\n                             if denominator > 0 else 0.0)\n                    revenue[v] = value\n                    baseline += value\n                    next_stock[v] = round(min(\n                        maximum[v], max(0.0, s - a - b) + regen[v]\n                    ), 2)\n                for v in self.reach[speed][position]:\n                    a, b, s = fixed_cap[v] + capacity, opp_cap[v], stocks[v]\n                    denominator = max(a + b, s)\n                    changed = ((a - b) * s / denominator\n                               if denominator > 0 else 0.0)\n                    reward = baseline + changed - revenue[v]\n                    if v != base:\n                        reward -= cost\n                    if v != position:\n                        reward -= 0.012\n                    new_score = score + discount * reward\n                    updated = next_stock[:]\n                    updated[v] = round(min(\n                        maximum[v], max(0.0, s - a - b) + regen[v]\n                    ), 2)\n                    new_path = path + [v]\n                    rank = new_score - discount * liabilities[v]\n                    children.append((rank, new_score, v, updated, new_path))\n            children.sort(key=lambda x: (-x[0], x[4]))\n\n            # Reserve spatial diversity: high immediate earnings at one node\n            # must not eliminate every route toward a better future region.\n            selected = []\n            per_position = [0] * n\n            limit = 2 if width >= 8 else 1\n            for child in children:\n                v = child[2]\n                if per_position[v] >= limit:\n                    continue\n                per_position[v] += 1\n                selected.append(child)\n                if len(selected) >= width:\n                    break\n            if not selected:\n                return None\n            final_rank = selected[0][0]\n            beam = [(score, v, stocks, path)\n                    for _, score, v, stocks, path in selected]\n        if final_rank > old_rank + 1e-8:\n            return beam[0][3]\n        return old_path[:]\n\n    def _sweep(self, units, base, plan, forecast, obs, horizon,\n               width, deadline, reverse=False):\n        preferred = "truck" if obs["turn"] < 4 else "scooter"\n        ids = sorted(units, key=lambda u: (units[u][0] != preferred, u))\n        if reverse:\n            ids.reverse()\n        for uid in ids:\n            if time.perf_counter() >= deadline:\n                break\n            path = self._optimize(\n                uid, units, base, plan, forecast, obs,\n                horizon, width, deadline\n            )\n            if path is not None:\n                plan[uid] = path\n\n    def act(self, obs):\n        started = time.perf_counter()\n        budget = max(0.0, float(TIME_BUDGET))\n        deadline = started + 0.58 * budget\n        self._prepare(obs)\n        n = int(obs["n_nodes"])\n        turn = int(obs["turn"])\n        horizon = min(7, max(1, 60 - turn))\n        own = obs["player_units"]\n        opponents = obs["opponent_units"]\n        base = int(obs["player_base"])\n        enemy_base = int(obs["opponent_base"])\n        activity = self._activity(obs)\n\n        frozen = [0.0] * n\n        for kind, node in opponents.values():\n            frozen[node] += CAP[kind]\n        static_forecast = [frozen[:] for _ in range(horizon)]\n\n        consecutive = self.last_turn is not None and turn == self.last_turn + 1\n        if consecutive and self.plan:\n            plan = self._warm(own, turn, horizon)\n        else:\n            plan = self._greedy(own, base, static_forecast, obs, horizon)\n\n        own_forecast = self._capacities(own, plan, horizon, n)\n        enemy_plan = self._greedy(\n            opponents, enemy_base, own_forecast, obs, horizon\n        )\n\n        if not self.conservative and activity > 0.15:\n            self._sweep(\n                opponents, enemy_base, enemy_plan, own_forecast, obs,\n                horizon, 5, min(deadline, started + 0.14 * budget)\n            )\n        forecast = self._forecast(\n            opponents, enemy_plan, activity, horizon, n\n        )\n\n        width = 5 if self.conservative else 12\n        self._sweep(\n            own, base, plan, forecast, obs, horizon, width,\n            min(deadline, started + 0.34 * budget)\n        )\n\n        # Refresh the opponent\'s best response to the revised destinations.\n        # Damping avoids assuming that simultaneous opponents can see our move.\n        if time.perf_counter() < started + 0.39 * budget and activity > 0.15:\n            own_forecast = self._capacities(own, plan, horizon, n)\n            response = self._greedy(\n                opponents, enemy_base, own_forecast, obs, horizon\n            )\n            if not self.conservative:\n                self._sweep(\n                    opponents, enemy_base, response, own_forecast, obs,\n                    horizon, 5, min(deadline, started + 0.44 * budget),\n                    reverse=True\n                )\n            revised = self._forecast(\n                opponents, response, activity, horizon, n\n            )\n            forecast = [\n                [0.45 * forecast[t][v] + 0.55 * revised[t][v]\n                 for v in range(n)]\n                for t in range(horizon)\n            ]\n\n        self._sweep(\n            own, base, plan, forecast, obs, horizon, width, deadline,\n            reverse=True\n        )\n\n        # Replay only against observed starting positions. Couriers have unique\n        # ids, no shared movement budget, and cannot be moved twice by this dict.\n        moves = {}\n        for uid in sorted(own):\n            path = plan.get(uid, [])\n            if not path:\n                continue\n            kind, source = own[uid]\n            destination = int(path[0])\n            if (destination != source and 0 <= destination < n\n                    and 0 <= self.dist[source][destination] <= SPEED[kind]):\n                moves[str(uid)] = int(destination)\n\n        self.plan = plan\n        self.last_turn = turn\n        self.previous_opponent = {\n            uid: int(data[1]) for uid, data in opponents.items()\n        }\n        return {"moves": moves}\n'
