_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Running cost: cost_p = 3.0 * (trucks of p not on p\'s base)\n#                       + 1.5 * (scooters of p not on p\'s base).\n# Moves happen before service. Units on their own base cost nothing.\n#\n# Conservative fallback: harvest only immediately reachable, uncontested stock,\n# reserve the full cost of returning home, and otherwise return home. No search,\n# speculative transit, randomness, persistent deployment plans, or stock forecasts.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\n\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\n\n\ndef payout(capacity, opponent_capacity, stock):\n    """The specification\'s service formula, including its zero-stock case."""\n    denominator = max(capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return capacity * stock / denominator\n\n\ndef preprocess_map(n_nodes, edges):\n    adjacency = [[] for _ in range(n_nodes)]\n    for a, b in edges:\n        if 0 <= a < n_nodes and 0 <= b < n_nodes and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n_nodes):\n        distance = [-1] * n_nodes\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] < 0:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n    return distances\n\n\ndef return_reserve(node, base, speed, cost, distances):\n    """Costs of a shortest return, excluding the free final arrival at home."""\n    distance = distances[node][base]\n    if distance < 0:\n        return float("inf")\n    turns = (distance + speed - 1) // speed\n    return cost * max(0, turns - 1)\n\n\ndef return_destination(node, base, speed, distances):\n    """A deterministic maximum-speed step along a shortest route home."""\n    if node == base:\n        return base\n    candidates = [\n        v for v in range(len(distances))\n        if 0 <= distances[node][v] <= speed\n        and 0 <= distances[v][base] < distances[node][base]\n    ]\n    if not candidates:\n        return node\n    return min(candidates, key=lambda v: (distances[v][base], v))\n\n\ndef make_plan(obs, distances):\n    units = obs.get("player_units", {})\n    n = len(distances)\n    base = int(obs["player_base"])\n    stock = obs.get("stock", [])\n    if int(obs.get("turn", 0)) >= N_TURNS:\n        return {}\n\n    opponent_capacity = [0] * n\n    for kind, node in obs.get("opponent_units", {}).values():\n        if kind in UNIT_TYPES and 0 <= node < n:\n            opponent_capacity[node] += UNIT_TYPES[kind][0]\n\n    # First establish an always-safe escape plan. Returning units reserve their\n    # destination so that a new harvester cannot dilute another unit\'s earnings.\n    plan = {}\n    occupied = [0] * n\n    for uid in sorted(units):\n        kind, node = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= node < n:\n            continue\n        capacity, cost, speed = UNIT_TYPES[kind]\n        destination = return_destination(node, base, speed, distances)\n        plan[uid] = destination\n        occupied[destination] += 1\n\n    # Handle already-deployed couriers first. Trucks exploit large initial stocks;\n    # scooters subsequently take smaller, inexpensive opportunities.\n    order = sorted(\n        plan,\n        key=lambda uid: (\n            units[uid][1] == base,\n            units[uid][0] != "truck",\n            uid,\n        ),\n    )\n    for uid in order:\n        kind, source = units[uid]\n        capacity, cost, speed = UNIT_TYPES[kind]\n        fallback = plan[uid]\n        occupied[fallback] -= 1\n        old_reserve = return_reserve(source, base, speed, cost, distances)\n        choices = []\n        for destination in range(n):\n            distance = distances[source][destination]\n            if destination == base or distance < 0 or distance > speed:\n                continue\n            if occupied[destination] or opponent_capacity[destination]:\n                continue\n            available_stock = stock[destination] if destination < len(stock) else 0.0\n            revenue = payout(\n                capacity, opponent_capacity[destination], available_stock\n            )\n            new_reserve = return_reserve(\n                destination, base, speed, cost, distances\n            )\n            # Profit minus the increase in the cost-to-return liability.\n            # A normal return step has this quantity zero even without service.\n            secured_gain = revenue - cost + old_reserve - new_reserve\n            margin = 0.5 if kind == "truck" else 0.25\n            if secured_gain >= margin:\n                choices.append((\n                    distance,\n                    -secured_gain,\n                    distances[destination][base],\n                    destination,\n                ))\n\n        if choices:\n            plan[uid] = min(choices)[3]\n        occupied[plan[uid]] += 1\n\n    # Against an idle opponent each paid harvesting step increases profit minus\n    # outstanding return liability by a strictly positive amount. Every fallback\n    # return preserves it or improves it. Thus repeated departures cannot burn\n    # accumulated profit, even as stocks are exhausted and regenerated.\n    return plan\n\n\ndef legal_action(plan, obs, distances):\n    units = obs.get("player_units", {})\n    n = len(distances)\n    moves = {}\n    for uid in sorted(plan):\n        if uid not in units or not isinstance(uid, str):\n            continue\n        kind, source = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= source < n:\n            continue\n        destination = int(plan[uid])\n        speed = UNIT_TYPES[kind][2]\n        if (\n            0 <= destination < n\n            and 0 <= distances[source][destination] <= speed\n            and destination != source\n        ):\n            moves[uid] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(a), int(b)) for a, b in edges))\n        if key != self._map_key:\n            self._distances = preprocess_map(n, edges)\n            self._map_key = key\n        if not 0 <= int(obs.get("player_base", -1)) < n:\n            return {"moves": {}}\n\n        # All work is bounded by the specified 13 nodes and 12 units. Each call\n        # replans from the observation, so skipped turns need no special handling.\n        plan = make_plan(obs, self._distances)\n        return legal_action(plan, obs, self._distances)\n'
